examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchButton(
        text = {{arrangeLabel}},
        onClick = { editing = !editing },
        variant = if (editing) MonarchButtonVariant.Primary else MonarchButtonVariant.Secondary,
        size = MonarchButtonSize.Sm,
    )
    MonarchDashboardGrid(
        items = tiles,
        key = { it.id },
        itemLabel = { it.title },
        layout = layout,
        onLayoutChange = { layout = it },
        span = { it.span },
        editing = editing,
    ) { tile ->
        MonarchWidget(title = tile.title) { MonarchText(text = tile.body) }
    }
    MonarchText(text = "Saved layout: ${layout.joinToString(", ")}", style = MonarchTextStyle.Caption)
}

