class Tile(val id: String, val title: String, val body: String, val span: MonarchDashboardGridSpan = MonarchDashboardGridSpan.One)
val tiles = listOf(
    Tile({{widgets.0.id}}, {{widgets.0.title}}, {{widgets.0.body}}, MonarchDashboardGridSpan.{{widgets.0.span|pascal}}),
    Tile({{widgets.1.id}}, {{widgets.1.title}}, {{widgets.1.body}}, MonarchDashboardGridSpan.columns({{widgets.1.span}})),
    Tile({{widgets.2.id}}, {{widgets.2.title}}, {{widgets.2.body}}),
)
var layout by remember { mutableStateOf(listOf({{layout.0}}, {{layout.1}}, {{layout.2}})) }
var editing by remember { mutableStateOf(false) }

examples.setup:
class Tile(val id: String, val title: String, val body: String, val span: MonarchDashboardGridSpan = MonarchDashboardGridSpan.One)
val tiles = listOf(
    Tile("figures", "Key figures", "128 open · 94% within target", MonarchDashboardGridSpan.Full),
    Tile("load", "Team load", "12 open across 4 people.", MonarchDashboardGridSpan.columns(2)),
    Tile("activity", "Recent activity", "3 updates today."),
)
var layout by remember { mutableStateOf(listOf("figures", "load", "activity")) }
var editing by remember { mutableStateOf(false) }

